import { PDF_COLORS, cleanPdfText, drawRadarChartCanvas, imageUrlToBase64 } from './pdfTheme.js';
import { savePdfUniversal } from './pdfGenerator.js';
import autoTable from 'jspdf-autotable';
import { getEffectiveLanguage } from '../i18n/translations.js';

const THEME_COLOR = PDF_COLORS.primary;
const ACCENT_COLOR = PDF_COLORS.accent;
const TEXT_DARK = PDF_COLORS.textDark;

/**
 * Dibuja la gráfica de evolución y tendencia por partido en Canvas 2D nativo para incrustar en el PDF.
 */
export const drawTrendLineChartCanvas = (perMatchMetrics = [], { isEn = false, width = 680, height = 300 } = {}) => {
  if (!perMatchMetrics || perMatchMetrics.length === 0) return null;
  try {
    const scale = 2;
    const canvas = document.createElement('canvas');
    canvas.width = Math.round(width * scale);
    canvas.height = Math.round(height * scale);
    const ctx = canvas.getContext('2d');
    ctx.scale(scale, scale);
    ctx.imageSmoothingEnabled = true;
    ctx.imageSmoothingQuality = 'high';

    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(0, 0, width, height);

    ctx.strokeStyle = '#E2E8F0';
    ctx.lineWidth = 1;
    ctx.strokeRect(1, 1, width - 2, height - 2);

    const pLeft = 45;
    const pRight = 20;
    const pTop = 38;
    const pBottom = 42;
    const chartW = width - pLeft - pRight;
    const chartH = height - pTop - pBottom;

    // Título
    ctx.font = 'bold 11px Arial, sans-serif';
    ctx.fillStyle = '#1B3A2D';
    ctx.textAlign = 'left';
    ctx.fillText(isEn ? 'MATCH PERFORMANCE TREND' : 'EVOLUCIÓN DE TENDENCIA POR PARTIDO', pLeft, 22);

    // Leyenda
    const legendItems = [
      { label: isEn ? 'Recoveries' : 'Recuperaciones', color: '#4CAF7D' },
      { label: isEn ? 'Losses' : 'Pérdidas', color: '#F59E0B' },
      { label: isEn ? 'Shots on Target' : 'Tiros a Puerta', color: '#D4A843' },
    ];
    let legX = width - pRight;
    ctx.textAlign = 'right';
    for (let i = legendItems.length - 1; i >= 0; i--) {
      const item = legendItems[i];
      ctx.font = 'bold 9.5px Arial, sans-serif';
      ctx.fillStyle = '#475569';
      ctx.fillText(item.label, legX, 22);
      const textW = ctx.measureText(item.label).width;
      legX -= textW + 6;
      ctx.beginPath();
      ctx.arc(legX, 19, 4, 0, Math.PI * 2);
      ctx.fillStyle = item.color;
      ctx.fill();
      legX -= 14;
    }

    const maxVal = Math.max(10, ...perMatchMetrics.map((d) => Math.max(d.recoveries || 0, d.losses || 0, d.shotsOwn || 0)));

    const getX = (i) => {
      if (perMatchMetrics.length <= 1) return pLeft + chartW / 2;
      return pLeft + (i / (perMatchMetrics.length - 1)) * chartW;
    };
    const getY = (val) => {
      return pTop + chartH - (val / maxVal) * chartH;
    };

    // Grid horizontal
    [0, 0.25, 0.5, 0.75, 1].forEach((pct) => {
      const y = pTop + chartH * (1 - pct);
      const val = Math.round(maxVal * pct);
      ctx.beginPath();
      ctx.strokeStyle = '#E2E8F0';
      ctx.lineWidth = 1;
      ctx.setLineDash([4, 4]);
      ctx.moveTo(pLeft, y);
      ctx.lineTo(width - pRight, y);
      ctx.stroke();
      ctx.setLineDash([]);

      ctx.font = '10px Arial, sans-serif';
      ctx.fillStyle = '#94A3B8';
      ctx.textAlign = 'right';
      ctx.fillText(String(val), pLeft - 6, y + 3);
    });

    const drawSeries = (key, color, isDashed = false) => {
      if (perMatchMetrics.length > 1) {
        ctx.beginPath();
        ctx.strokeStyle = color;
        ctx.lineWidth = 2.5;
        if (isDashed) ctx.setLineDash([5, 5]);
        else ctx.setLineDash([]);

        perMatchMetrics.forEach((d, i) => {
          const x = getX(i);
          const y = getY(d[key] || 0);
          if (i === 0) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);
        });
        ctx.stroke();
        ctx.setLineDash([]);
      }

      // Puntos
      perMatchMetrics.forEach((d, i) => {
        const x = getX(i);
        const y = getY(d[key] || 0);
        ctx.beginPath();
        ctx.arc(x, y, 4.5, 0, Math.PI * 2);
        ctx.fillStyle = color;
        ctx.fill();
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 1.5;
        ctx.stroke();
      });
    };

    drawSeries('recoveries', '#4CAF7D');
    drawSeries('losses', '#F59E0B');
    drawSeries('shotsOwn', '#D4A843', true);

    // Eje X
    perMatchMetrics.forEach((d, i) => {
      const x = getX(i);
      ctx.font = 'bold 9.5px Arial, sans-serif';
      ctx.fillStyle = '#152C22';
      ctx.textAlign = 'center';
      const label = `vs ${(d.rival || 'Rival').substring(0, 8)}`;
      ctx.fillText(label, x, height - pBottom + 16);
      if (d.date) {
        ctx.font = '8px Arial, sans-serif';
        ctx.fillStyle = '#94A3B8';
        const dStr = d.date.split('-').reverse().slice(0, 2).join('/');
        ctx.fillText(dStr, x, height - pBottom + 28);
      }
    });

    return canvas.toDataURL('image/png', 0.95);
  } catch (e) {
    console.warn('[drawTrendLineChartCanvas] Error:', e);
    return null;
  }
};

/**
 * Exporta un informe completo en PDF con el análisis comparativo multipartido
 */
export const exportMultiMatchAnalysisPDF = async ({
  selectedMatches = [],
  perMatchMetrics = [],
  aggregates = {},
  viewMode = 'AVERAGES',
  activeTeam = null,
  language = null,
}) => {
  const effLang = getEffectiveLanguage(language);
  const isEn = effLang === 'English (EN)' || effLang === 'en';
  window.dispatchEvent(new CustomEvent('m11-loading', { detail: { show: true, message: isEn ? 'Generating Multi-Match Analysis Report...' : 'Generando Informe de Análisis Multipartido...' } }));
  await new Promise((r) => setTimeout(r, 150));

  try {
    const { jsPDF } = await import('jspdf');
    const doc = new jsPDF('p', 'mm', 'a4');
    const pageW = doc.internal.pageSize.getWidth();
    const pageH = doc.internal.pageSize.getHeight();

    const teamName = cleanPdfText(activeTeam?.nombre || activeTeam?.name || (isEn ? 'My Team' : 'Mi Equipo'));
    const category = cleanPdfText(activeTeam?.categoria || activeTeam?.category || (isEn ? 'Official' : 'Oficial'));
    const isAverages = viewMode === 'AVERAGES';
    const modeLabel = isAverages
      ? (isEn ? 'MATCH AVERAGES' : 'PROMEDIOS POR PARTIDO')
      : (isEn ? 'CUMULATIVE TOTALS' : 'TOTALES ACUMULADOS');

    // ── CABECERA INSTITUCIONAL ────────────────────────────────────────────────
    doc.setFillColor(...THEME_COLOR);
    doc.rect(0, 0, pageW, 36, 'F');
    doc.setFillColor(...ACCENT_COLOR);
    doc.rect(0, 34, pageW, 2, 'F');

    // Logo Míster11 a la izquierda
    const logoData = await imageUrlToBase64('/logo_mister11.png', 'M11', false);
    if (logoData) {
      try {
        doc.addImage(logoData, 'PNG', 14, 5, 18, 18);
      } catch (e) {
        console.warn('Error dibujando logo:', e);
      }
    }

    doc.setTextColor(255, 255, 255);
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(14);
    doc.text(isEn ? 'MÍSTER 11 · MULTI-MATCH COMPARATIVE ANALYSIS' : 'MÍSTER 11 · ANÁLISIS COMPARATIVO MULTIPARTIDO', 36, 15);

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8.5);
    doc.setTextColor(210, 230, 220);
    const dateStr = new Date().toLocaleDateString(isEn ? 'en-US' : 'es-ES');
    doc.text(
      isEn
        ? `${teamName} (${category}) · Sample: ${selectedMatches.length} matches · Issued: ${dateStr}`
        : `${teamName} (${category}) · Muestra: ${selectedMatches.length} partidos · Emisión: ${dateStr}`,
      36,
      23
    );

    // Escudo del equipo si está disponible
    if (activeTeam?.escudo) {
      const shieldData = await imageUrlToBase64(activeTeam.escudo, teamName, true);
      if (shieldData) {
        try {
          doc.addImage(shieldData, 'PNG', pageW - 30, 5, 18, 18);
        } catch (e) {
          console.warn('Error dibujando escudo:', e);
        }
      }
    }

    let y = 44;

    // ── BANNER DE RESUMEN DE MUESTRA Y MODO DE ANÁLISIS ────────────────────────
    doc.setFillColor(248, 250, 252);
    doc.roundedRect(12, y, pageW - 24, 18, 3, 3, 'F');
    doc.setDrawColor(226, 232, 240);
    doc.roundedRect(12, y, pageW - 24, 18, 3, 3, 'S');

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8.5);
    doc.setTextColor(...THEME_COLOR);
    doc.text(isEn ? 'ANALYSIS SAMPLE SUMMARY' : 'RESUMEN DE LA MUESTRA ANALIZADA', 18, y + 6);

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7.5);
    doc.setTextColor(71, 85, 105);

    const firstDate = selectedMatches[0]?.date ? selectedMatches[0].date.split('-').reverse().join('/') : '-';
    const lastDate = selectedMatches[selectedMatches.length - 1]?.date
      ? selectedMatches[selectedMatches.length - 1].date.split('-').reverse().join('/')
      : '-';

    doc.text(
      isEn
        ? `Analysis period: ${firstDate} to ${lastDate}   |   Selected matches: ${selectedMatches.length} matches   |   Mode: ${modeLabel}`
        : `Período de análisis: ${firstDate} al ${lastDate}   |   Partidos seleccionados: ${selectedMatches.length} encuentros   |   Modo: ${modeLabel}`,
      18,
      y + 12
    );

    y += 24;

    // ── BLOQUE DE KPIS TÁCTICOS ───────────────────────────────────────────────
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(9.5);
    doc.setTextColor(...THEME_COLOR);
    doc.text(isEn ? 'KEY PERFORMANCE INDICATORS (COLLECTIVE KPIS)' : 'INDICADORES CLAVE DE RENDIMIENTO (KPIS COLECTIVOS)', 12, y);
    y += 4;

    const cardW = (pageW - 24 - 9) / 4; // 4 tarjetas con 3 gaps de 3mm
    const cardH = 22;

    const kpiData = [
      {
        title: isEn ? 'SHOTS ON TARGET' : 'TIROS A PUERTA',
        value: isAverages
          ? `${aggregates.avgShotsOwn || 0} / ${aggregates.avgShotsRival || 0}`
          : `${aggregates.totalShotsOwn || 0} / ${aggregates.totalShotsRival || 0}`,
        sub: isAverages
          ? (isEn ? 'Avg. Own vs Rival' : 'Prom. Propio vs Rival')
          : (isEn ? 'Total Own vs Rival' : 'Total Propio vs Rival'),
        color: [76, 175, 125], // Verde Campo #4CAF7D
      },
      {
        title: isEn ? 'DUELS WON (%)' : 'DUELOS GANADOS (%)',
        value: `${aggregates.avgDuelPct || 0}%`,
        sub: isEn ? 'Overall duel efficiency' : 'Efectividad global en duelos',
        color: [212, 168, 67], // Oro Institucional #D4A843
      },
      {
        title: isEn ? 'RECOVERIES / LOSSES' : 'RECUPERACIONES / PÉRDIDAS',
        value: isAverages
          ? `${aggregates.avgRecoveries || 0} / ${aggregates.avgLosses || 0}`
          : `${aggregates.totalRecoveries || 0} / ${aggregates.totalLosses || 0}`,
        sub: isAverages
          ? (isEn ? 'Avg. Rec / Loss' : 'Prom. Rec / Pérd')
          : (isEn ? 'Total Rec / Loss' : 'Total Rec / Pérd'),
        color: [245, 158, 11], // Ámbar #F59E0B
      },
      {
        title: isEn ? 'COUNTER-ATTACK EFF.' : 'EFECT. CONTRAATAQUE',
        value: `${aggregates.avgCounterEff || 0}%`,
        sub: isEn ? 'Offensive conversion ratio' : 'Ratio de conversión ofensiva',
        color: [27, 58, 45], // Verde Institucional Oscuro #1B3A2D
      },
    ];

    kpiData.forEach((kpi, idx) => {
      const cX = 12 + idx * (cardW + 3);
      doc.setFillColor(255, 255, 255);
      doc.roundedRect(cX, y, cardW, cardH, 2.5, 2.5, 'F');
      doc.setDrawColor(226, 232, 240);
      doc.roundedRect(cX, y, cardW, cardH, 2.5, 2.5, 'S');

      // Pequeña barra superior de color
      doc.setFillColor(...kpi.color);
      doc.roundedRect(cX, y, cardW, 2.5, 1, 1, 'F');

      doc.setFont('helvetica', 'bold');
      doc.setFontSize(6.5);
      doc.setTextColor(100, 116, 139);
      doc.text(kpi.title, cX + cardW / 2, y + 7, { align: 'center' });

      doc.setFont('helvetica', 'bold');
      doc.setFontSize(10.5);
      doc.setTextColor(...THEME_COLOR);
      doc.text(kpi.value, cX + cardW / 2, y + 14, { align: 'center' });

      doc.setFont('helvetica', 'normal');
      doc.setFontSize(5.5);
      doc.setTextColor(148, 163, 184);
      doc.text(kpi.sub, cX + cardW / 2, y + 19, { align: 'center' });
    });

    y += cardH + 8;

    // ── GRÁFICAS DE RENDIMIENTO TÁCTICO ──────────────────────────────────────
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(9.5);
    doc.setTextColor(...THEME_COLOR);
    doc.text(isEn ? 'TACTICAL PERFORMANCE CHARTS' : 'GRÁFICAS DE RENDIMIENTO TÁCTICO', 12, y);
    y += 4;

    const shotsScore = Math.min(99, Math.max(10, Math.round((aggregates.avgShotsOwn || 0) * 12)));
    const duelsScore = Math.min(99, Math.max(10, aggregates.avgDuelPct || 50));
    const recRatio = (aggregates.totalRecoveries || 1) / Math.max(1, aggregates.totalLosses || 1);
    const recScore = Math.min(99, Math.max(10, Math.round(recRatio * 50)));
    const counterScore = Math.min(99, Math.max(10, aggregates.avgCounterEff || 40));
    const goalsBalance = (aggregates.totalGoalsFor || 0) - (aggregates.totalGoalsAgainst || 0);
    const goalsScore = Math.min(99, Math.max(10, Math.round(50 + goalsBalance * 5)));

    const tacticalMetrics = [
      { label: isEn ? 'Shots on Target' : 'Tiros Puerta', value: shotsScore },
      { label: isEn ? 'Duels Won' : 'Duelos Ganados', value: duelsScore },
      { label: isEn ? 'Recoveries' : 'Recuperaciones', value: recScore },
      { label: isEn ? 'Loss Control' : 'Control Pérdidas', value: counterScore },
      { label: isEn ? 'Counter-Attacks' : 'Contraataques', value: goalsScore },
    ];

    const trendImg = drawTrendLineChartCanvas(perMatchMetrics, { isEn, width: 680, height: 320 });
    const radarImg = drawRadarChartCanvas(tacticalMetrics, 440);

    const chartHeightMm = 54;
    if (trendImg && radarImg) {
      doc.addImage(trendImg, 'PNG', 12, y, 112, chartHeightMm);
      doc.addImage(radarImg, 'PNG', 128, y, 70, chartHeightMm);
      y += chartHeightMm + 8;
    } else if (trendImg) {
      doc.addImage(trendImg, 'PNG', 12, y, pageW - 24, chartHeightMm);
      y += chartHeightMm + 8;
    } else if (radarImg) {
      const radarSize = 65;
      const radarX = (pageW - radarSize) / 2;
      doc.addImage(radarImg, 'PNG', radarX, y, radarSize, radarSize);
      y += radarSize + 8;
    }

    // ── TABLA DETALLADA POR PARTIDO ───────────────────────────────────────────
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(9.5);
    doc.setTextColor(...THEME_COLOR);
    doc.text(isEn ? 'DETAILED MATCH-BY-MATCH BREAKDOWN' : 'DESGLOSE DETALLADO PARTIDO A PARTIDO', 12, y);
    y += 4;

    const tableHeaders = isEn
      ? ['Date', 'Opponent / Match', 'Result', 'Shots (O/R)', '% Duels', 'Rec / Loss', 'Fouls (F/A)', 'Cards']
      : ['Fecha', 'Rival / Partido', 'Resultado', 'Tiros (P/R)', '% Duelos', 'Rec / Pérd', 'Faltas (F/C)', 'Tarjetas'];

    const tableRows = perMatchMetrics.map((pm) => {
      const fDate = pm.date ? pm.date.split('-').reverse().join('/') : '--/--';
      const rivalName = cleanPdfText(pm.rival || (isEn ? 'Opponent' : 'Rival'));
      const scoreStr = `${pm.goalsFor ?? 0} - ${pm.goalsAgainst ?? 0}`;
      const shotsStr = `${pm.shotsOwn ?? 0} / ${pm.shotsRival ?? 0}`;
      const duelStr = `${pm.duelPct ?? 0}%`;
      const recStr = `${pm.recoveries ?? 0} / ${pm.losses ?? 0}`;
      const foulsStr = `${pm.foulsFavor ?? 0} / ${pm.foulsAgainst ?? 0}`;
      const cardsStr = isEn ? `Y:${pm.cardsOwn ?? 0} | R:${pm.cardsRival ?? 0}` : `A:${pm.cardsOwn ?? 0} | R:${pm.cardsRival ?? 0}`;

      return [fDate, `vs ${rivalName}`, scoreStr, shotsStr, duelStr, recStr, foulsStr, cardsStr];
    });

    autoTable(doc, {
      startY: y,
      head: [tableHeaders],
      body: tableRows,
      theme: 'grid',
      headStyles: {
        fillColor: THEME_COLOR,
        textColor: [255, 255, 255],
        fontStyle: 'bold',
        fontSize: 8,
        halign: 'center',
      },
      bodyStyles: {
        fillColor: [255, 255, 255],
        textColor: TEXT_DARK,
        fontSize: 7.5,
        halign: 'center',
        cellPadding: 2,
      },
      alternateRowStyles: {
        fillColor: PDF_COLORS.bgLight,
      },
      columnStyles: {
        0: { halign: 'center', cellWidth: 20 },
        1: { halign: 'left', fontStyle: 'bold' },
        2: { halign: 'center', fontStyle: 'bold' },
      },
      margin: { left: 12, right: 12 },
    });

    let finalY = doc.lastAutoTable.finalY + 8;

    // Si queda poco espacio, añadir página para observaciones técnicas
    if (finalY > pageH - 40) {
      doc.addPage();
      finalY = 24;
    }

    // ── CAJA DE CONCLUSIONES TÁCTICAS DEL CUERPO TÉCNICO ─────────────────────
    doc.setFillColor(250, 248, 240);
    doc.roundedRect(12, finalY, pageW - 24, 22, 2.5, 2.5, 'F');
    doc.setFillColor(...ACCENT_COLOR);
    doc.rect(12, finalY, 3, 22, 'F');

    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8.5);
    doc.setTextColor(...THEME_COLOR);
    doc.text(
      isEn ? 'TECHNICAL STAFF METHODOLOGICAL NOTES & CONCLUSIONS' : 'OBSERVACIONES Y NOTAS METODOLÓGICAS (CUERPO TÉCNICO)',
      18,
      finalY + 6
    );

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7.5);
    doc.setTextColor(71, 85, 105);

    const goalDiff = (aggregates.totalGoalsFor || 0) - (aggregates.totalGoalsAgainst || 0);
    const balanceText = goalDiff >= 0
      ? (isEn ? `Positive goal balance (+${goalDiff} goals)` : `Balance goleador positivo (+${goalDiff} goles)`)
      : (isEn ? `Goal balance to improve (${goalDiff} goals)` : `Balance goleador a corregir (${goalDiff} goles)`);
    const conclusionText = isEn
      ? `Sample of ${selectedMatches.length} matches with overall duel efficiency of ${aggregates.avgDuelPct || 0}%. Average shots on target: ${aggregates.avgShotsOwn || 0} for vs ${aggregates.avgShotsRival || 0} against. ${balanceText}. Recommended to consolidate counter-pressing and clinical offensive transitions.`
      : `Muestra de ${selectedMatches.length} partidos con efectividad global en duelos del ${aggregates.avgDuelPct || 0}%. Promedio de tiros a favor: ${aggregates.avgShotsOwn || 0} vs ${aggregates.avgShotsRival || 0} recibidos. ${balanceText}. Se recomienda consolidar la presión tras pérdida y finalizar las transiciones ofensivas.`;

    const splitNotes = doc.splitTextToSize(cleanPdfText(conclusionText), pageW - 36);
    doc.text(splitNotes, 18, finalY + 12);

    // ── PIE DE PÁGINA OFICIAL EN TODAS LAS PÁGINAS ────────────────────────────
    const totalPages = doc.internal.getNumberOfPages();
    for (let p = 1; p <= totalPages; p++) {
      doc.setPage(p);
      doc.setFillColor(...THEME_COLOR);
      doc.rect(0, pageH - 9, pageW, 9, 'F');
      doc.setTextColor(255, 255, 255);
      doc.setFont('helvetica', 'normal');
      doc.setFontSize(7);
      doc.text(
        isEn ? 'Míster 11 Club Engine · Tactical Intelligence & Analytics Module' : 'Míster 11 Club Engine · Módulo de Inteligencia y Análisis Táctico',
        12,
        pageH - 3.5
      );
      doc.text(
        isEn ? `Page ${p} of ${totalPages}` : `Página ${p} de ${totalPages}`,
        pageW - 12,
        pageH - 3.5,
        { align: 'right' }
      );
    }

    const safeName = teamName.replace(/\s+/g, '_');
    const fileName = `Analisis_Comparativo_${safeName}_${new Date().toISOString().slice(0, 10)}.pdf`;

    await savePdfUniversal(doc, fileName);
  } catch (err) {
    console.error('[exportMultiMatchAnalysisPDF] Error:', err);
    alert(isEn ? 'There was an error generating the multi-match analysis PDF.' : 'Hubo un error al generar el PDF de análisis multipartido.');
  } finally {
    window.dispatchEvent(new CustomEvent('m11-loading', { detail: { show: false } }));
  }
};
