/**
 * src/hooks/useMatchSheet.js
 * Míster11 — Ciclo de vida del Acta Oficial de Partido
 *
 * Gestiona:
 *  - Escucha en tiempo real del RSVP del jugador y del `actual` del entrenador
 *  - Actualización del estado del jugador en el acta (presente/ausente/tarde…)
 *  - Override manual de minutos
 *  - Cierre del acta (closed: true + minutos reales calculados)
 *  - Reapertura del acta (solo admin)
 */
import { useState, useEffect } from 'react';
import {
  doc,
  collection,
  getDocs,
  onSnapshot,
  updateDoc,
  setDoc,
  serverTimestamp,
  getDoc
} from 'firebase/firestore';
import { db } from '../firebaseConfig';
import { useAuth } from '../context/AuthContext';
import {
  calculateAllPlayerMinutes,
  buildSmartMatchSheetActual,
  calculateMinutesFromEvents,
  getUnifiedMatchEvents,
  getEffectiveMatchDuration,
  cleanseImpossibleMatchEvents
} from '../utils/minutesEngine';
import { calculatePlayerMatchStats } from '../utils/playerMatchStats';
import { calcMixedRating, deriveStatsFromEvents } from '../utils/ratingFormula';
import { showToast } from '../utils/toast';
import { t } from '../i18n/index.js';

/**
 * Hook principal del Acta Oficial.
 *
 * @param {string} teamPath   - Ruta del equipo ej: "users/uid/teams/teamId"
 * @param {string} matchId    - ID del partido
 * @param {Object} matchData  - Datos actuales del partido (titulares, suplentes, events…)
 * @param {Array}  players    - Lista de jugadores del equipo
 */
export const useMatchSheet = (teamPath, matchId, matchData, players = []) => {
  const { user } = useAuth();
  const [sheet, setSheet] = useState(null);      // { rsvp, actual, closed, closedAt, closedBy }
  const [loading, setLoading] = useState(true);

  const cleanPath = teamPath ? teamPath.replace(/^\/+|\/+$/g, '') : '';
  const isValid = cleanPath && matchId;

  // 1. Escucha en tiempo real del documento del acta dentro del partido
  useEffect(() => {
    if (!isValid) { setLoading(false); return; }

    const matchDocRef = doc(db, `${cleanPath}/matches`, matchId);
    const unsub = onSnapshot(matchDocRef, (snap) => {
      if (snap.exists()) {
        const data = snap.data();
        setSheet({
          rsvp:               data.playerRsvp  || {},
          actual:             data.actaOficial?.actual             || {},
          closed:             data.actaOficial?.closed             || false,
          closedWithWarnings: data.actaOficial?.closedWithWarnings || false,
          warnings:           data.actaOficial?.warnings           || [],
          closedAt:           data.actaOficial?.closedAt           || null,
          closedBy:           data.actaOficial?.closedBy           || null,
        });
      } else {
        setSheet({ rsvp: {}, actual: {}, closed: false, closedWithWarnings: false, warnings: [], closedAt: null, closedBy: null });
      }
      setLoading(false);
    }, (err) => {
      console.warn('[useMatchSheet] Error escuchando acta:', err);
      setLoading(false);
    });

    return () => unsub();
  }, [cleanPath, matchId, isValid]);

  /**
   * Prellenado Inteligente del Acta Oficial.
   * - En partido iniciado o terminado: alineación = PRESENTE + minutos calculados por events.
   * - No sobreescribe modificaciones manuales del míster (source === 'manual').
   * - No depende de que haya RSVP de los jugadores.
   */
  const smartPrefill = async () => {
    if (!isValid || !user || sheet?.closed) return;
    try {
      const smartActual = buildSmartMatchSheetActual(
        matchData,
        sheet?.actual || {},
        sheet?.rsvp || {},
        user.uid,
        { preserveManual: true }
      );
      const matchDocRef = doc(db, `${cleanPath}/matches`, matchId);
      await updateDoc(matchDocRef, {
        'actaOficial.actual': smartActual,
      });
      showToast(t('matchSheet.prefill_smart_success'), 'success');
    } catch (err) {
      console.error('[useMatchSheet] Error en prellenado inteligente:', err);
      showToast(t('matchSheet.prefill_smart_error'), 'error');
      throw err;
    }
  };

  /**
   * Prellenar el `actual` desde el RSVP actual.
   * going → presente | not_going → ausente | late → tarde | justified → justificado
   * No sobreescribe entradas ya confirmadas por el míster (preserva cambios manuales).
   */
  const prefillFromRsvp = async () => {
    if (!isValid || !user || sheet?.closed) return;
    const rsvpMap = sheet?.rsvp || {};
    const currentActual = sheet?.actual || {};

    const RSVP_TO_STATUS = {
      going: 'presente',
      not_going: 'ausente',
      late: 'tarde',
      justified: 'justificado',
    };

    const updates = {};
    Object.entries(rsvpMap).forEach(([pid, rsvpData]) => {
      if (!currentActual[pid] || currentActual[pid].source !== 'manual') {
        const status = RSVP_TO_STATUS[rsvpData.status] || null;
        if (status) {
          updates[`actaOficial.actual.${pid}`] = {
            ...(currentActual[pid] || {}),
            status,
            at: new Date().toISOString(),
            by: user.uid,
            source: 'rsvp_prefill',
          };
        }
      }
    });

    if (Object.keys(updates).length === 0) {
      showToast(t('matchSheet.prefill_rsvp_empty'), 'info');
      return;
    }

    try {
      const matchDocRef = doc(db, `${cleanPath}/matches`, matchId);
      await updateDoc(matchDocRef, updates);
      showToast(t('matchSheet.prefill_rsvp_success'), 'success');
    } catch (err) {
      console.error('[useMatchSheet] Error prellenando desde RSVP:', err);
      showToast(t('matchSheet.prefill_rsvp_error'), 'error');
      throw err;
    }
  };

  /**
   * Actualizar el estado de asistencia de un jugador en el acta.
   * Solo el staff puede llamar a esta función.
   * @param {string} playerId
   * @param {'presente'|'ausente'|'tarde'|'justificado'|'lesionado'|'sin_registro'} status
   * @param {number} [lateMin]         - Minutos de retraso (si status === 'tarde')
   * @param {number|null} [minutesOverride] - Override manual de minutos jugados
   */
  const updatePlayerStatus = async (playerId, status, lateMin = null, minutesOverride = null) => {
    if (!isValid || !user) return;
    try {
      const matchDocRef = doc(db, `${cleanPath}/matches`, matchId);
      const existing = sheet?.actual?.[playerId] || {};
      const duration = parseInt(matchData?.duration || matchData?.duracion || 90, 10);
      const rawTitulares = Array.isArray(matchData?.titulares) ? matchData.titulares : (matchData?.alineacion?.titulares || []);
      const rawSuplentes = Array.isArray(matchData?.suplentes) ? matchData.suplentes : (matchData?.alineacion?.suplentes || []);
      const allEvents = getUnifiedMatchEvents(matchData);

      const effectiveOverride = minutesOverride !== null ? minutesOverride : (existing.minutesOverride ?? null);
      const effectiveLateMin = lateMin !== null ? lateMin : (existing.lateMin ?? null);

      const minutesCalc = calculateMinutesFromEvents(
        playerId,
        allEvents,
        rawTitulares,
        rawSuplentes,
        duration,
        effectiveOverride,
        status,
        effectiveLateMin
      );

      const payload = {
        ...existing,
        status,
        minutes: minutesCalc.minutes,
        minuteSource: minutesCalc.source,
        detail: minutesCalc.detail,
        source: 'manual',
        at: new Date().toISOString(),
        by: user.uid,
      };
      if (lateMin !== null) payload.lateMin = lateMin;
      if (minutesOverride !== null) payload.minutesOverride = minutesOverride;

      // Actualización optimista inmediata en useMatchSheet
      setSheet(prev => {
        if (!prev) return prev;
        return {
          ...prev,
          actual: {
            ...(prev.actual || {}),
            [playerId]: payload
          }
        };
      });

      await updateDoc(matchDocRef, {
        [`actaOficial.actual.${playerId}`]: payload,
      });
      return payload;
    } catch (err) {
      console.error('[useMatchSheet] Error actualizando estado:', err);
      throw err;
    }
  };

  /**
   * Actualiza la calificación individual (1 a 10) otorgada por el míster a un jugador.
   */
  const updatePlayerRating = async (playerId, rating) => {
    if (!isValid || !user) return;
    try {
      const matchDocRef = doc(db, `${cleanPath}/matches`, matchId);
      const parsed = (rating === '' || rating === null || rating === undefined) ? null : parseFloat(rating);
      await updateDoc(matchDocRef, {
        [`playerRatings.${playerId}`]: parsed,
        [`ratings.${playerId}`]: parsed,
        [`actaOficial.actual.${playerId}.rating`]: parsed,
      });
      showToast(t('matchSheet.tactical_grade_saved'), 'success');
    } catch (err) {
      console.error('[useMatchSheet] Error actualizando calificación:', err);
      throw err;
    }
  };

  /**
   * Depurar eventos imposibles de la bitácora y recalcular acta.
   */
  const cleanseEvents = async () => {
    if (!isValid || !user || !matchId) return;
    try {
      const allEvents = getUnifiedMatchEvents(matchData);
      const rawTitulares = Array.isArray(matchData.titulares)
        ? matchData.titulares
        : (matchData.alineacion?.titulares || []);
      const duration = getEffectiveMatchDuration(matchData);

      const { cleansedEvents, removedCount, details } = cleanseImpossibleMatchEvents(allEvents, rawTitulares, duration);

      if (removedCount === 0) {
        showToast(t('matchSheet.log_already_clean'), 'info');
        return { removedCount: 0, details: [] };
      }

      // Recalcular marcador desde eventos válidos
      const derivedGoalsFor = cleansedEvents.filter(e => e.isValid !== false && (e.type === 'gol_local' || e.type === 'goal_own')).length;
      const derivedGoalsAgainst = cleansedEvents.filter(e => e.isValid !== false && (e.type === 'gol_rival' || e.type === 'goal_rival')).length;

      // Recalcular acta oficial
      const currentActual = sheet?.actual || {};
      const updatedActual = buildSmartMatchSheetActual(
        { ...matchData, events: cleansedEvents, liveStatsEvents: cleansedEvents },
        currentActual,
        sheet?.rsvp || {},
        user.uid,
        { preserveManual: false }
      );

      const nowIso = new Date().toISOString();
      const matchDocRef = doc(db, `${cleanPath}/matches`, matchId);
      await updateDoc(matchDocRef, {
        events: cleansedEvents,
        liveStatsEvents: cleansedEvents,
        goalsFor: derivedGoalsFor,
        goalsAgainst: derivedGoalsAgainst,
        'actaOficial.actual': updatedActual,
        'actaOficial.totalDuration': duration,
        warningsResolved: true,
        warningsResolvedAt: serverTimestamp(),
        cleanedAt: nowIso,
        cleanedBy: user.uid,
        cleanedByName: user.displayName || 'Staff',
        updatedAt: serverTimestamp(),
      });

      const count = removedCount > 0 ? removedCount : (matchData?.warnings?.length || 1);
      showToast(t('matchSheet.anomalies_resolved', { count }), 'success');
      return { removedCount, details };
    } catch (err) {
      console.error('[useMatchSheet] Error depurando bitácora:', err);
      showToast(t('matchSheet.log_debug_error'), 'error');
      throw err;
    }
  };

  /**
   * Actualizar solo el override de minutos de un jugador.
   * Permite al cuerpo técnico corregir minutos en cualquier momento.
   */
  const updateMinutesOverride = async (playerId, minutes) => {
    if (!isValid || !user) return;
    try {
      const matchDocRef = doc(db, `${cleanPath}/matches`, matchId);
      const parsed = (minutes === '' || minutes === null || minutes === undefined) ? null : Math.max(0, parseInt(minutes, 10));
      const existing = sheet?.actual?.[playerId] || {};
      const nowIso = new Date().toISOString();
      const updates = {
        [`actaOficial.actual.${playerId}.minutesOverride`]: parsed,
        [`actaOficial.actual.${playerId}.by`]: user.uid,
        [`actaOficial.actual.${playerId}.source`]: 'manual',
        [`actaOficial.actual.${playerId}.at`]: nowIso,
      };
      let newStatus = existing.status || 'sin_registro';
      if (parsed !== null) {
        updates[`actaOficial.actual.${playerId}.minutes`] = parsed;
        updates[`actaOficial.actual.${playerId}.minuteSource`] = 'override';
        if (parsed > 0 && (newStatus === 'sin_registro' || newStatus === 'ausente')) {
          newStatus = 'presente';
          updates[`actaOficial.actual.${playerId}.status`] = 'presente';
        }
      }

      const updatedPlayerEntry = {
        ...existing,
        minutesOverride: parsed,
        by: user.uid,
        source: 'manual',
        at: nowIso,
        ...(parsed !== null ? {
          minutes: parsed,
          minuteSource: 'override',
          status: newStatus
        } : {})
      };

      // Actualización optimista local inmediata
      setSheet(prev => {
        if (!prev) return prev;
        return {
          ...prev,
          actual: {
            ...(prev.actual || {}),
            [playerId]: updatedPlayerEntry
          }
        };
      });

      await updateDoc(matchDocRef, updates);
      return updatedPlayerEntry;
    } catch (err) {
      console.error('[useMatchSheet] Error actualizando override de minutos:', err);
      throw err;
    }
  };

  /**
   * CERRAR O CONFIRMAR MANUALMENTE EL ACTA.
   * Calcula los minutos reales de cada jugador con el motor de minutos (respetando al 100%
   * cualquier override manual introducido por el entrenador) y congela/confirma el acta.
   * Solo el staff puede confirmar.
   */
  const closeMatchSheet = async (withWarnings = false, warningsList = [], forceSave = true) => {
    if (!isValid || !user) throw new Error('Sin usuario o partido activo.');
    if (sheet?.closed && !forceSave) return;

    try {
      const duration = getEffectiveMatchDuration(matchData);
      const currentActual = sheet?.actual || {};

      const finalActual = buildSmartMatchSheetActual(
        matchData,
        currentActual,
        sheet?.rsvp || {},
        user.uid,
        { preserveManual: true }
      );

      // D1: Calcular y asignar la nota mixta si el jugador no tiene override manual
      const unifEvents = getUnifiedMatchEvents(matchData);
      const gkStatsMap = {};

      Object.entries(finalActual).forEach(([pid, act]) => {
        if (act && (act.minutes > 0 || act.minutesOverride > 0)) {
          const playerObj = players.find(p => String(p.id) === String(pid));
          const role = playerObj?.position || playerObj?.posicion || null;
          const stats = deriveStatsFromEvents(pid, unifEvents, role);

          if (!act.rating && !matchData?.playerRatings?.[pid]) {
            const { mixedRating } = calcMixedRating(stats, act.attitude || 3);
            act.rating = mixedRating;
          }

          if (role === 'POR' || stats.isGoalkeeper) {
            const saves = stats.saves || 0;
            const conceded = stats.conceded || 0;
            const totalShots = saves + conceded;
            const savePct = totalShots > 0 ? Math.round((saves / totalShots) * 100) : 0;
            gkStatsMap[pid] = {
              saves,
              conceded,
              cleanSheet: stats.cleanSheet ? 1 : 0,
              penaltySaves: stats.penaltySaves || 0,
              claims: stats.claims || 0,
              errorGoal: stats.errorGoal || 0,
              savePercentage: savePct,
              rating: act.rating || 6.0
            };
          }
        }
      });

      const matchDocRef = doc(db, `${cleanPath}/matches`, matchId);
      await updateDoc(matchDocRef, {
        'actaOficial.actual': finalActual,
        'actaOficial.closed': true,
        'actaOficial.closedWithWarnings': Boolean(withWarnings),
        'actaOficial.warnings': warningsList || [],
        'actaOficial.closedAt': serverTimestamp(),
        'actaOficial.closedBy': user.uid,
        'actaOficial.closedByName': user.displayName || 'Staff',
        'actaOficial.totalDuration': duration,
        'actaOficial.reopenedAt': null,
        status: 'Terminado',
        actaReabierta: false,
        reopenedAt: null,
        gkStats: gkStatsMap,
      });

      if (withWarnings) {
        showToast(t('matchSheet.closed_with_warnings'), 'warning');
      } else {
        showToast(t('matchSheet.closed_success'), 'success');
      }

      // ── Sincronizar stats.gk acumuladas en la ficha de cada portero ──
      Object.entries(gkStatsMap).forEach(async ([gkId, currentGkStats]) => {
        try {
          const pRef = doc(db, `${cleanPath}/players`, gkId);
          const pSnap = await getDoc(pRef);
          if (pSnap.exists()) {
            const pData = pSnap.data() || {};
            const existingGk = pData.stats?.gk || {
              matches: 0,
              saves: 0,
              conceded: 0,
              cleanSheets: 0,
              penaltySaves: 0,
              claims: 0,
              errorGoals: 0,
              savePercentage: 0
            };
            const newMatches = (existingGk.matches || 0) + 1;
            const newSaves = (existingGk.saves || 0) + (currentGkStats.saves || 0);
            const newConceded = (existingGk.conceded || 0) + (currentGkStats.conceded || 0);
            const newCleanSheets = (existingGk.cleanSheets || 0) + (currentGkStats.cleanSheet || 0);
            const newPenSaves = (existingGk.penaltySaves || 0) + (currentGkStats.penaltySaves || 0);
            const newClaims = (existingGk.claims || 0) + (currentGkStats.claims || 0);
            const newErrGoals = (existingGk.errorGoals || 0) + (currentGkStats.errorGoal || 0);
            const totShots = newSaves + newConceded;
            const newSavePct = totShots > 0 ? Math.round((newSaves / totShots) * 100) : 0;

            await updateDoc(pRef, {
              'stats.gk': {
                matches: newMatches,
                saves: newSaves,
                conceded: newConceded,
                cleanSheets: newCleanSheets,
                penaltySaves: newPenSaves,
                claims: newClaims,
                errorGoals: newErrGoals,
                savePercentage: newSavePct
              }
            });
          }
        } catch (e) {
          console.warn('[useMatchSheet] Error actualizando stats.gk del portero:', e);
        }
      });

      // ── REC-8: Sincronizar notaMedia acumulada en la ficha de cada jugador ──
      try {
        const matchesSnap = await getDocs(collection(db, `${cleanPath}/matches`));
        const allMatches = matchesSnap.docs.map(d => ({ id: d.id, ...d.data() }));
        Object.keys(finalActual || {}).forEach((pid) => {
          try {
            const pStats = calculatePlayerMatchStats(pid, allMatches);
            if (pStats?.avgRating && pStats.avgRating !== '-' && !isNaN(Number(pStats.avgRating))) {
              const pRef = doc(db, `${cleanPath}/players`, pid);
              updateDoc(pRef, { notaMedia: parseFloat(pStats.avgRating) }).catch(() => {});
            }
          } catch (_) {}
        });
      } catch (_) {}

      return { finalActual, duration, gkStatsMap };
    } catch (err) {
      console.error('[useMatchSheet] Error cerrando acta:', err);
      showToast(t('matchSheet.close_error'), 'error');
      throw err;
    }
  };

  /**
   * REABRIR EL ACTA / PARTIDO (solo admin / staff).
   * Resetea closed a false, registra trazabilidad y permite correcciones en todas las pestañas.
   */
  const reopenMatchSheet = async (motivo = '') => {
    if (!isValid || !user) return;
    try {
      const matchDocRef = doc(db, `${cleanPath}/matches`, matchId);
      await updateDoc(matchDocRef, {
        'actaOficial.closed': false,
        'actaOficial.closedWithWarnings': false,
        'actaOficial.reopenedAt': serverTimestamp(),
        'actaOficial.reopenedBy': user.uid,
        'actaOficial.reopenReason': motivo || 'Reapertura para corrección autorizada por el cuerpo técnico',
        status: 'Pendiente',
      });
      showToast(t('matchSheet.reopened_info'), 'info');
    } catch (err) {
      console.error('[useMatchSheet] Error reabriendo acta:', err);
      showToast(t('matchSheet.reopen_error'), 'error');
      throw err;
    }
  };

  // Helpers de lectura del sheet
  const getPlayerActual = (playerId) => sheet?.actual?.[playerId] || null;
  const getPlayerRsvp   = (playerId) => sheet?.rsvp?.[playerId]   || null;
  const isClosed = sheet?.closed === true;

  /**
   * Detectar discrepancias: jugador dijo "iré" pero el míster lo marcó ausente (o viceversa).
   */
  const getDiscrepancies = () => {
    if (!sheet) return [];
    const RSVP_TO_STATUS = { going: 'presente', not_going: 'ausente', late: 'tarde', justified: 'justificado' };
    return Object.entries(sheet.rsvp || {}).reduce((acc, [pid, rsvpData]) => {
      const actualStatus = sheet.actual?.[pid]?.status;
      const expectedFromRsvp = RSVP_TO_STATUS[rsvpData.status];
      if (actualStatus && expectedFromRsvp && actualStatus !== expectedFromRsvp) {
        acc.push({ playerId: pid, rsvp: rsvpData.status, actual: actualStatus });
      }
      return acc;
    }, []);
  };

  return {
    sheet,
    loading,
    isClosed,
    getPlayerActual,
    getPlayerRsvp,
    getDiscrepancies,
    smartPrefill,
    prefillFromRsvp,
    updatePlayerStatus,
    updateMinutesOverride,
    updatePlayerRating,
    closeMatchSheet,
    reopenMatchSheet,
    cleanseEvents,
  };
};
